def esc(value):return html.escape(str(value))

def main():
    inventory=json.loads((a.OUT/'inventory.json').read_text())
    extra=json.loads((a.OUT/'inventory_extra.json').read_text())
    rows=inventory['models']+extra['models']
    valid=[r for r in rows if 'preview' in r]
    missing=[r for r in rows if 'error' in r]
    # Contact sheets for material/geometry variants, also reviewed independently.
    variants=[r for r in inventory['models'] if 'preview' in r and any(x in r['model'] for x in ('_pir_','_nmd_'))]
    for start in range(0,len(variants),12):
        sheet=Image.new('RGB',(1600,220*((len(variants[start:start+12])+3)//4)),(24,29,37))
        for i,row in enumerate(variants[start:start+12]):
            sheet.paste(Image.open(a.OUT/row['preview']).resize((400,220)),((i%4)*400,(i//4)*220))
        sheet.save(a.OUT/f'variants_{start//12+1}.jpg',quality=92)
    content=['''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Истребители — разбор стиля и направления доработки</title><style>
body{margin:0;background:#121820;color:#dce3ea;font:17px/1.6 system-ui}main{max-width:1400px;margin:auto;padding:32px}h1,h2,h3{color:#fff;line-height:1.2}a{color:#8fd4e9}p{max-width:1100px}.note{color:#afbdca}table{border-collapse:collapse;width:100%}td,th{padding:12px;border-bottom:1px solid #37424d;vertical-align:top;text-align:left}img{max-width:100%;height:auto}section{margin:42px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:20px}article{background:#1a222c;padding:18px;border-radius:8px}article p{font-size:15px}code{color:#b1d7b8;overflow-wrap:anywhere}input,select{font:inherit;background:#202c38;color:#fff;border:1px solid #61778b;padding:9px;margin:4px}details{margin:16px 0}summary{cursor:pointer}small{color:#acb9c5}nav{position:sticky;top:0;background:#121820ed;padding:10px 0;z-index:1}
</style><main><h1>Истребители: стиль и направления доработки</h1>
<p>Анализ файлов текущей установки FL_MOD, 16 ноября 2026. Все изображения получены из моделей; это офлайн-превью, не кадры игры и не новые концепты.</p>''']
    content.append(f'<p>Проверены {len(inventory["models"])} уникальных путей моделей истребителей и отдельный эталон в этом наборе: {len(inventory["models"])-len(missing)} файлов доступны, {len(missing)} путей не найдены. Дополнительно разобраны {len(extra["models"])} отдельных неиспользуемых файлов вне активных ссылок. В галерее {len(valid)} превью; это не число уникальных дизайнов.</p>')
    content.append('''<section><h2>Что именно сделано в rh_alt_elite</h2>
<p>Основной корпус, фонарь, двигатели и хвост сохраняют геометрию rh_elite с погрешностью экспорта менее 0,000001 единицы. Две простые крыльевые детали заменены составной системой: корневые узлы, секции выдвижения и поворотные внешние панели. Добавлен нижний узел Rh_root. HpWeapon01/02 и огни законцовок размещены на новых внешних секциях.</p>
<p>Полный ближний меш: <b>1514 → 1832 треугольника (+21%)</b>, <b>9 → 14 mesh-частей</b>, включая два служебных треугольника в альтернативе. Число точек крепления осталось 71. Первичный подсчёт только Level0 пропускал новые прямые VMeshPart: корректный анализ обязан учитывать оба способа хранения.</p>
<p>На сравнении одинаковые масштаб, свет и камеры. Два состояния справа — первый и последний ключи только Sc_extend wing. Это разбор данных канала; порядок и направление его проигрывания в игре здесь не проверялись.</p>
<a href="rh_comparison.jpg"><img src="rh_comparison.jpg" alt="rh_elite и два состояния rh_alt_elite"></a>
<p><b>Принцип для следующих моделей:</b> сохранить узнаваемые крупные объёмы, переработать один выразительный конструктивный узел, показать его работу и использовать совместимую палитру. На мой взгляд, именно это даёт здесь больший эффект, чем рост плотности сетки по всей обшивке.</p></section>''')
    content.append('<section><h2>Семейства</h2><table><tr><th>Семейство / модели</th><th>Что определяет стиль</th><th>Направление доработки</th></tr>')
    for key,(title,models,style,approach,idea) in family_notes.items():
        content.append(f'<tr><td><b>{esc(title)}</b><br><small>{esc(models)}</small></td><td>{esc(style)}</td><td>{esc(approach)}<p>{esc(idea)}</p></td></tr>')
    content.append('''</table></section><section><h2>Три первых опыта</h2>
<ol><li><b>rh_fighter — компактный механический перехватчик.</b> Сохранить нос, кабину и круглый кормовой узел. Переработать боковые секции: короткое усиленное основание, второй более тонкий щиток, понятная направляющая и небольшой ход. По сложности и размаху он должен оставаться младше rh_alt_elite.</li>
<li><b>li_elite — усиленный силовой набор.</b> Сохранить план крыльев и кабину. Добавить корневой обтекатель, утопленный стык с двигателем, более убедительную рамку сопла. Сначала оценить силуэт и крупные фаски, затем панельные детали.</li>
<li><b>co_fighter из папки CORSAIR — читаемая несущая рама.</b> Переработать соединение двигателей и высоких плоскостей с центральным корпусом. Оставить открытые промежутки, красные акценты и ступенчатые формы. Это позволит проверить иной язык дизайна без повторения рейнландских крыльев.</li></ol>
<p>Мой первый выбор — <b>rh_fighter</b>: проще оценить результат рядом с твоим эталоном. Для него достаточно подготовить два варианта крупных форм, вид сверху, сбоку, спереди/сзади и короткую демонстрацию механизма. После выбора — UV, нормали, LOD, hardpoints и SUR.</p>
<h2>Практические ограничения</h2><ul>
<li>Сначала силуэт и большие объёмы, потом швы и фактура. Не превращать тёмные участки diffuse в геометрические вмятины: там могут быть краска и запечённая тень.</li>
<li>Сглаживать выборочно: корпус Рейнланда и Либерти не должен стать округлым. У Бретонии и Кусари важно сохранить плавные переходы.</li>
<li>В rh_alt_elite новые детали хранятся без своей цепочки LOD. При тиражировании подхода нужно сделать дальнее упрощение; увеличение числа деталей и проходов отрисовки может быть важнее самих 318 добавленных треугольников.</li>
<li>Проверять оружие в обеих крайних позах, оси шарниров, SUR, отрыв деталей и damage caps. Наличие анимации и SUR в файлах ещё не доказывает их корректность в полёте.</li>
<li>Материалы семейства по возможности переиспользовать. Различие внешнего вида лучше получать геометрией и аккуратной раскладкой UV, сохраняя общий атлас.</li>
</ul></section><section><h2>Галерея моделей</h2>
<p class="note">Нулевое положение конструкций; не обязательно полётное. У каждой модели два ракурса, размер подогнан индивидуально. Нет вооружения, эффектов, игрового стекла, normal maps и анимации материалов. Серый участок может означать отсутствующий материал в объявленной библиотеке. В счётчик входят служебные части.</p>
<nav><input id="search" placeholder="Поиск модели или nickname" aria-label="Поиск"><select id="family"><option value="">Все семейства</option>''')
    for key,notes in family_notes.items():content.append(f'<option value="{key}">{esc(notes[0])}</option>')
    content.append('</select><label><input type="checkbox" id="variants" checked>Показывать NMD/PIR</label><span id="count"></span></nav><div class="grid">')
    for row in valid:
        model=row['model'];family=model.split('/')[1];stem=Path(model).stem
        is_variant=any(x in model for x in ('_nmd_','_pir_'))
        note=model_notes.get(stem,family_notes.get(family,('','','','',''))[3])
        if is_variant:note='Вариант семейства; сравнивать материал и состав деталей с базовым корпусом. '+note
        unresolved=[m['name'] for m in row['material_info'] if m['kind']=='MISSING']
        content.append(f'<article data-family="{esc(family)}" data-variant="{int(is_variant)}" data-search="{esc(model+" "+" ".join(row["aliases"]))}"><h3>{esc(stem)}</h3><a href="{esc(row["preview"])}"><img loading="lazy" src="{esc(row["preview"])}" alt="{esc(stem)}"></a><p>{esc(note)}</p><p><b>{row["triangles"]}</b> треугольников · {len(row["parts"])} частей · {row["hardpoint_count"]} точек крепления</p><details><summary>Источник и ограничения</summary><code>{esc(model)}</code><p>Архетипы: {esc(", ".join(row["aliases"]))}</p><p>Материалы без определения: {esc(", ".join(unresolved) or "нет")}</p><p>{esc("; ".join(row.get("warnings",[])))}</p></details></article>')
    content.append('</div></section><section><h2>Покрытие и пробелы</h2><p>Отбор выполнен из списков ships активного bin/freelancer.ini; дубли nickname сведены, пути CMP объединены. Классы 0/1/4/5/6/7, отдельные модели Кочевников и ku_dragon включены; грузовые, служебные и крупные катсценовые FIGHTER исключены. Резервные копии с bkp/orig и копии по имени не трактуются как новые дизайны.</p>')
    content.append('<p>В конфигурации есть ссылки на отсутствующие файлы. Их стиль не выдуман: соответствующие модели помечены как недоступные. Эти записи сами по себе не доказывают проблему в текущем прохождении.</p><details><summary>Отсутствующие модели</summary><ul>')
    for row in missing:content.append(f'<li><code>{esc(row["model"])}</code></li>')
    content.append('''</ul></details><p>Машиночитаемые результаты: <a href="inventory.json">основной каталог</a>, <a href="inventory_extra.json">дополнительные файлы</a>, <a href="rh_comparison.json">разбор rh_elite</a>.</p>
<p>Рабочие модели и игра не изменялись. Новая геометрия на этом этапе не создавалась.</p></section></main><script>
const search=document.querySelector('#search'),family=document.querySelector('#family'),variants=document.querySelector('#variants');
function filter(){let n=0;document.querySelectorAll('article').forEach(e=>{const show=e.dataset.search.toLowerCase().includes(search.value.toLowerCase())&&(!family.value||family.value===e.dataset.family)&&(variants.checked||e.dataset.variant==='0');e.hidden=!show;if(show)n++;});document.querySelector('#count').textContent=' '+n+' моделей';}
[search,family,variants].forEach(e=>e.addEventListener('input',filter));filter();</script></html>''')
    (a.OUT/'index.html').write_text('\n'.join(content),encoding='utf-8')
    print('Report:',a.OUT/'index.html','previews:',len(valid),'missing:',len(missing))

